contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint minsum, uint am) public {
        require(minsum == 0);
        require(am == 0);

        c.SetMinSum(minsum); if (__ESBMC_reverted()) return;

        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint minsumBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            reverted &&
            c.balances(address(this)) == balBefore &&
            c.MinSum() == minsumBefore &&
            balBefore >= minsumBefore &&
            balBefore >= am
        );
    }

    receive() external payable {
        revert();
    }
}

