pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 minsum, uint256 am) internal {
        minsum = 0;
        am = 0;
        try c.SetMinSum(minsum) {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 minsumBefore;
        try c.MinSum() returns (uint256 __r) { minsumBefore = __r; } catch { return; }
        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted &&
            c.balances(address(this)) == balBefore &&
            c.MinSum() == minsumBefore &&
            balBefore >= minsumBefore &&
            balBefore >= am);
    }

    function testFuzz_run(uint256 minsum, uint256 am) public {
        _run(minsum, am);
    }

    receive() external payable {
        revert();
    }
}
